contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address target, address to, uint256 amount) public payable {
        require(to != address(0));

        c.freezeAccount(target, true); if (__ESBMC_reverted()) return;
        c.freezeAccount(target, false); if (__ESBMC_reverted()) return;

        uint256 senderBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 recipientBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;
        require(senderBefore >= amount);

        bool reverted;
        c.transfer(to, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!reverted && c.balanceOf(address(this)) == senderBefore - amount && c.balanceOf(to) == recipientBefore + amount);
    }
}

